  async function upload(file){const target=selected;if(target?.classList.contains('project-gallery'))return report('Choose an individual Gallery image in Layers, not the gallery container.');if(!target?.isConnected)return report('Select a card/frame or add an Image/Video section first.');if(busy)return report('Finish or cancel the current upload first.');busy=new AbortController();const controller=busy;$('.editor-progress').hidden=false;$('#media-upload').disabled=true;try{const asset=await M.optimize(file,$('#media-quality').value,controller.signal,(fraction,message)=>{$('#media-progress').value=fraction;$('#media-progress-label').textContent=message;});if(controller.signal.aborted)throw new DOMException('Upload cancelled.','AbortError');asset.id=uid();await db.put('assets',asset.id,asset);if(controller.signal.aborted)throw new DOMException('Upload cancelled.','AbortError');if(!target.isConnected)throw Error('The selected frame was removed. The optimized file is in the media library.');cache.set(asset.id,asset);const url=URL.createObjectURL(asset.blob);urls.set(asset.id,url);attach(target,asset,url);$('#media-result').textContent=`${asset.name}: ${M.bytes(asset.originalSize)} → ${M.bytes(asset.size)} (${Math.max(0,Math.round((1-asset.size/asset.originalSize)*100))}% smaller)${asset.width?` · ${asset.width} × ${asset.height}`:''}. ${asset.warning||''}`;await save(false);report('Optimized media inserted. Export page + media when ready to publish.');library();}catch(error){report(error.name==='AbortError'?'Upload cancelled. Existing media was kept.':'Upload not inserted: '+error.message,error.name!=='AbortError');}finally{busy=null;$('.editor-progress').hidden=true;$('#media-upload').disabled=false;$('#media-upload').value='';}}
  async function library(){try{const files=await db.all('assets'),list=$('#media-library'),used=new Set([...main.querySelectorAll('[data-asset-id]')].map(el=>el.dataset.assetId));list.replaceChildren();let total=0;for(const asset of files){total+=asset.size;const row=document.createElement('div');row.className='editor-asset';const label=document.createElement('span');label.textContent=`${asset.name} · ${M.bytes(asset.size)}${used.has(asset.id)?' · used here':''}`;const use=document.createElement('button');use.type='button';use.textContent='Use';use.addEventListener('click',()=>chosen(el=>{cache.set(asset.id,asset);if(!urls.has(asset.id))urls.set(asset.id,URL.createObjectURL(asset.blob));attach(el,asset,urls.get(asset.id));library();}));row.append(label,use);list.append(row);}$('#media-budget').textContent=`${files.length} assets · ${M.bytes(total)} stored locally across pages. Duplicates share media.${total>25*1024*1024?' Large library: use hosted video and export regular backups.':''}`;}catch(error){$('#media-budget').textContent='Storage unavailable: '+error.message;}}
  function mediaBindings(){
    $('#media-upload').addEventListener('change',e=>{if(e.target.files?.[0])upload(e.target.files[0]);});$('#cancel-upload').addEventListener('click',()=>busy?.abort());bindSel('#media-fit',fit);
    bindSel('#media-position',(el,v)=>{const p={center:[50,50],top:[50,0],bottom:[50,100],left:[0,50],right:[100,50]}[v];[el.dataset.focalX,el.dataset.focalY]=p;position(el);set('#media-focal-x',p[0],'%');set('#media-focal-y',p[1],'%');});for(const a of ['x','y'])bindSel('#media-focal-'+a,(el,v)=>{el.dataset['focal'+a.toUpperCase()]=v;position(el);},'%');
    bindSel('#media-aspect',(el,v)=>{if(el.dataset.mediaMode==='fullscreen'){fit(el,'cover');set('#media-fit','cover');}if(v==='original'){if(el.dataset.originalGridHeight!==undefined){const old=el.dataset.originalGridHeight;old?el.parentElement.style.setProperty('--editor-card-height',old):el.parentElement.style.removeProperty('--editor-card-height');delete el.dataset.originalGridHeight;}if(el.dataset.originalAspect){const original=JSON.parse(el.dataset.originalAspect);for(const[prop,val]of Object.entries(original))val?css(el,prop,val):el.style.removeProperty(prop);delete el.dataset.originalAspect;delete el.dataset.naturalMedia;}return;}if(!el.dataset.originalAspect)el.dataset.originalAspect=JSON.stringify({'aspect-ratio':el.style.aspectRatio,'min-height':el.style.minHeight,'height':el.style.height});el.dataset.naturalMedia=String(v==='auto');css(el,'aspect-ratio',v);css(el,'min-height','0px');if(el.matches('[data-project-grid] > .project')){if(el.dataset.originalGridHeight===undefined)el.dataset.originalGridHeight=el.parentElement.style.getPropertyValue('--editor-card-height');const m=media(el),ratio=v==='auto'?(m?.naturalWidth||m?.videoWidth||4)/(m?.naturalHeight||m?.videoHeight||5):v.split('/').map(Number).reduce((x,y)=>x/y);el.parentElement.style.setProperty('--editor-card-height',Math.round(el.getBoundingClientRect().width/ratio)+'px');}else css(el,'height','auto');});bindSel('#media-alt',(el,v)=>el.querySelectorAll('img').forEach(m=>m.alt=v));bindSel('#media-caption',(el,v)=>{let caption=el.querySelector(':scope > .editor-caption');if(!v.trim()){caption?.remove();return;}if(!caption){caption=document.createElement('p');caption.className='editor-caption';el.append(caption);}caption.textContent=v;scan();});
    for(const p of ['controls','loop','muted','autoplay'])bindSel('#video-'+p,(el,v)=>el.querySelectorAll('video,audio').forEach(m=>{m[p]=v;if(p==='muted')m.toggleAttribute('muted',v);if(p==='autoplay'&&v){m.muted=true;m.setAttribute('muted','');$('#video-muted').checked=true;m.play().catch(()=>report('Autoplay was blocked by this browser. Use the video play button.'));}if(p==='autoplay'&&!v)m.pause();}));
    $('#media-preview').addEventListener('click',()=>chosen(el=>{const m=media(el)||el;if(m.requestFullscreen)m.requestFullscreen().catch(error=>report('Full screen unavailable: '+error.message,true));else report('Full screen preview is not supported in this browser.');}));$('#media-remove').addEventListener('click',()=>chosen(el=>{el.querySelectorAll(':scope > img,:scope > video,:scope > audio').forEach(m=>{m.pause?.();m.remove();});el.classList.remove('editor-media-background','editor-media-frame');el.style.setProperty('--image','none');commit();hydrate();}));$('#refresh-library').addEventListener('click',library);
    $('#insert-media-url').addEventListener('click',()=>{try{chosen(el=>{const url=new URL($('#media-url').value);if(!['https:','http:'].includes(url.protocol))throw Error('Use an https:// media URL.');const ext=url.pathname.split('.').pop().toLowerCase(),kind=['mp4','webm','mov'].includes(ext)?'video':['mp3','m4a','ogg','wav'].includes(ext)?'audio':['jpg','jpeg','png','webp','avif','gif'].includes(ext)?'image':null;if(!kind)throw Error('Use a direct URL ending in a supported media extension.');attach(el,{kind,name:url.pathname.split('/').pop()},url.href);report('Linked media added. External files are not compressed or included in exports.');});}catch(error){report(error.message,true);}});
  }
  function download(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
  async function pageAssets(state,portable=false){const doc=new DOMParser().parseFromString('<main>'+state.html+'</main>','text/html'),ids=new Set([...doc.querySelectorAll('[data-asset-id]')].map(el=>el.dataset.assetId)),files=[];for(const id of ids){const a=cache.get(id)||await db.get('assets',id);if(!a){const node=[...doc.querySelectorAll('[data-asset-id]')].find(el=>el.dataset.assetId===id);if(node?.getAttribute('src')&&!node.getAttribute('src').startsWith('blob:')){if(!portable)continue;try{const response=await fetch(new URL(node.getAttribute('src'),location.href));if(!response.ok)throw Error('Media request failed');const blob=await response.blob();const result=await M.optimize(new File([blob],node.dataset.filename||'Published media',{type:blob.type}),'original');files.push({...result,id});continue;}catch{throw Error('A published media file could not be included in the backup. Reinsert it from your computer, or keep its existing asset file with your project. No incomplete backup was created.');}}throw Error('A referenced media file is missing. Reinsert it or restore a backup before exporting.');}files.push(a);}return files;}
  const dataURL=blob=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});
  async function exportBackup(){try{if(busy)throw Error('Finish or cancel the upload first.');const state=snapshot(),files=await pageAssets(state,true);if(files.reduce((s,a)=>s+a.size,0)>200*1024*1024)throw Error('Backup exceeds 200 MB. Use hosted video or export page + media instead.');const encoded=[];for(const{blob,...a}of files)encoded.push({...a,data:await dataURL(blob)});download(new Blob([JSON.stringify({format:'nani-editor',version:1,page:slug,state,assets:encoded})],{type:'application/json'}),slug+'-editable-backup.json');report('Editable backup downloaded. Keep it private; it contains this page and its media.');}catch(error){report('Backup failed: '+error.message,true);}}
  function sanitize(html){const t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('script,iframe,object,embed,link,meta,style,base').forEach(el=>el.remove());t.content.querySelectorAll('*').forEach(el=>{for(const a of [...el.attributes])if(/^on/i.test(a.name)||['srcdoc','formaction'].includes(a.name)||['href','src','action','poster','xlink:href'].includes(a.name)&&/^\s*(javascript:|vbscript:|data:text\/html)/i.test(a.value))el.removeAttribute(a.name);});return t.innerHTML;}
  function validateSettings(raw){const s={};for(const k of ['marginX','marginY','sectionGap','padX','padY','radius','gapX','gapY','columns'])if(Number.isFinite(raw?.[k]))s[k]=Math.max(-100,Math.min(1000,raw[k]));if(/^#[0-9a-f]{6}$/i.test(raw?.bg))s.bg=raw.bg;return s;}
  async function importBackup(file){try{if(busy)throw Error('Finish or cancel the upload first.');if(file.size>280*1024*1024)throw Error('Backup is too large.');const b=JSON.parse(await file.text());if(b.format!=='nani-editor'||b.version!==1||typeof b.state?.html!=='string'||!Array.isArray(b.assets))throw Error('Not a supported portfolio editor backup.');if(b.page!==slug)throw Error(`This backup belongs to ${b.page}. Open that page to import it.`);if(!confirm('Replace this page with the backup? You can undo until reload.'))return;const imported=[];for(const a of b.assets){if(typeof a.id!=='string'||!/^[a-zA-Z0-9-]+$/.test(a.id)||typeof a.data!=='string'||!/^data:(image\/(jpeg|png|gif|webp|avif)|video\/(mp4|webm)|audio\/(mpeg|mp4|ogg|wav));base64,/.test(a.data))throw Error('Unsupported media in backup.');const blob=await(await fetch(a.data)).blob();if(blob.size>100*1024*1024)throw Error('Backup media exceeds 100 MB.');imported.push({...a,data:undefined,blob,size:blob.size});}for(const a of imported){a.ext=M.extension(a.blob.type);a.kind=a.blob.type.split('/')[0];a.type=a.blob.type;a.name=typeof a.name==='string'?a.name.slice(0,200):'Imported media';await db.put('assets',a.id,a);cache.set(a.id,a);}const state={...b.state,html:sanitize(b.state.html),settings:validateSettings(b.state.settings)};for(const field of ['userCSS','baseCSS'])if(typeof state[field]!=='string'||state[field].length>50000||/@import|url\s*\(|expression\s*\(|[<>]/i.test(state[field]))state[field]=undefined;await restore(state);commit();await save();report('Backup imported and saved locally. Undo is available.');}catch(error){report('Import failed: '+error.message,true);}finally{$('#import-backup').value='';}}
  async function exportPage(){try{if(busy)throw Error('Finish or cancel the upload first.');await save(false);const state=snapshot(),files=await pageAssets(state),doc=document.documentElement.cloneNode(true),pageMain=doc.querySelector('main');pageMain.innerHTML=state.html;const output=files.map(a=>({name:`assets/editor-${a.id}.${a.ext}`,blob:a.blob}));pageMain.querySelectorAll('[data-asset-id]').forEach(el=>{const a=files.find(a=>a.id===el.dataset.assetId);if(a)el.setAttribute('src',`./assets/editor-${a.id}.${a.ext}`);});doc.querySelector('#portfolio-user-styles').textContent=userStyle.textContent;doc.querySelectorAll('.debug-menu,.debug-trigger,#codex-browser-sidebar-comments-root').forEach(el=>el.remove());doc.querySelector('body').classList.remove('debug-open','debug-editing','debug-grid-overlay','debug-outlines');doc.querySelectorAll('[contenteditable],[spellcheck]').forEach(el=>{el.removeAttribute('contenteditable');el.removeAttribute('spellcheck');});output.unshift({name:slug+'.html',blob:new Blob(['<!doctype html>\n'+doc.outerHTML],{type:'text/html'})});output.push({name:'PUBLISH-README.txt',blob:new Blob([`Merge ${slug}.html and assets/ into your existing portfolio folder, keeping existing CSS, JS, fonts and original images. This is an update package, not a complete website. Publish your website folder through GitHub/Vercel. External URLs remain external. Local drafts are not deployed automatically. Never deploy editable JSON backups, source archives, or poster source folders.\n`])});download(await M.zip(output),slug+'-publish-update.zip');report('Page and separate optimized media exported. Merge into your existing site before publishing.');}catch(error){report('Export failed: '+error.message,true);}}
  async function storageInfo(){try{const e=await navigator.storage?.estimate?.();$('#storage-info').textContent=e?`${M.bytes(e.usage||0)} used of approximately ${M.bytes(e.quota||0)} local browser storage. Drafts are device/browser specific. Private browsing or clearing site data can erase them; download backups regularly.`:'Storage estimates unavailable. Keep a downloaded backup and test saving with a reload.';}catch(error){$('#storage-info').textContent='Storage estimate unavailable: '+error.message;}}
  async function migrateMedia(){for(const el of main.querySelectorAll('img[src^="data:"],video[src^="data:"],audio[src^="data:"]')){if(el.dataset.assetId)continue;try{const blob=await(await fetch(el.src)).blob();if(!/^(image|video|audio)\//.test(blob.type))continue;const a={id:uid(),blob,name:el.alt||'Previous upload',size:blob.size,originalSize:blob.size,kind:blob.type.split('/')[0],type:blob.type,ext:M.extension(blob.type)};await db.put('assets',a.id,a);el.dataset.assetId=a.id;cache.set(a.id,a);}catch(error){report('Previous upload migration failed: '+error.message+'. Keep an exported backup.',true);}}}
  async function boot(){
    buildUI();scan();baseline=snapshot();
    try{const draft=await db.get('drafts',key);if(draft?.html){await restore({...draft,html:sanitize(draft.html),settings:validateSettings(draft.settings)});report('Restored local draft · '+new Date(draft.savedAt||Date.now()).toLocaleString());}await migrateMedia();await hydrate();}catch(error){report('Local storage unavailable: '+error.message+'. Editing still works; keep an exported backup.',true);}
    const columnGroup=$('#column-layout-controls');columnGroup.insertAdjacentHTML('beforeend','<div id="all-column-content"></div>');columnGroup.parentElement.prepend(columnGroup);columnGroup.querySelector('summary').textContent='Columns · 1–7 / media / text';columnGroup.querySelector('.column-content-editor').hidden=true;columnGroup.querySelectorAll(':scope > details').forEach(n=>n.hidden=true);$('#column-count').max='7';
    renderSettings();bindings();columnGroup.querySelectorAll(':scope > details').forEach(n=>n.hidden=true);mediaBindings();syncGlobal();layers();syncSelection();columnPanel();refreshColumnHandles();ready=true;history=[snapshot()];cursor=0;historyButtons();toggle(false);
    $('#export-backup').addEventListener('click',exportBackup);$('#export-page').addEventListener('click',exportPage);$('#import-backup').addEventListener('change',e=>{if(e.target.files?.[0])importBackup(e.target.files[0]);});$('#storage-check').addEventListener('click',storageInfo);
    main.addEventListener('click',event=>{if(!body.classList.contains('debug-editing')){const link=event.target.closest('[data-link]');if(link&&!event.target.closest('a,input,button,textarea,select'))location.href=link.dataset.link;return;}const el=event.target.closest('[data-editable-section]');if(!el||el.dataset.editorLocked==='true')return;event.preventDefault();event.stopPropagation();select(el,event.target.closest('[data-editable-text]'));},true);
    main.addEventListener('keydown',e=>{if(!body.classList.contains('debug-editing')&&e.key==='Enter'&&e.target.dataset.link)location.href=e.target.dataset.link;});
    document.addEventListener('keydown',event=>{const typing=event.target.closest('input,textarea,select,[contenteditable="true"]');if(event.key==='Escape'){toggle(false);event.target.blur?.();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='s'&&body.classList.contains('debug-open')){event.preventDefault();save();return;}if(typing)return;if(event.key.toLowerCase()==='d'&&!event.metaKey&&!event.ctrlKey&&!event.altKey){event.preventDefault();toggle();}if(!body.classList.contains('debug-open'))return;if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'){event.preventDefault();travel(event.shiftKey?1:-1);return;}if((event.key==='Delete'||event.key==='Backspace')&&selected?.isConnected){event.preventDefault();removeSelected();return;}if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='j'){event.preventDefault();duplicate();}});
    document.addEventListener('submit',event=>{if(event.target.id!=='contact-form')return;event.preventDefault();const data=new FormData(event.target);if($('.form-status'))$('.form-status').textContent='Opening your email app…';location.href=`mailto:hi@andrew.com?subject=${encodeURIComponent('Portfolio enquiry from '+data.get('name'))}&body=${encodeURIComponent(data.get('message')+'\n\nFrom: '+data.get('name')+' ('+data.get('email')+')')}`;});
    const viewport=()=>$('#debug-viewport').textContent=`${innerWidth} × ${innerHeight} · ${slug}`;addEventListener('resize',()=>{viewport();if(settings.gapX<0||settings.gapY<0)renderSettings();});viewport();
    addEventListener('beforeunload',event=>{if(revision!==saved||busy){event.preventDefault();event.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&ready&&revision!==saved)save(false);});
    window.__portfolioEditor={getDraft:()=>db.get('drafts',key),getState:snapshot,open:()=>toggle(true),select:el=>select(el),save,exportBackup,exportPage,upload,ready:true};if(new URLSearchParams(location.search).has('editor'))toggle(true);
  }
  boot().catch(error=>{report('Editor could not start: '+error.message+'. Your source page is unchanged. Reload to retry.',true);console.error('Portfolio editor:',error);});
